/* ── QR Code Engine (self-contained, no external dependency) ── */

/* Minimal self-contained QR Code encoder (Byte mode only), no dependencies.
   Algorithm follows ISO/IEC 18004. */
var QRMath = (function(){
  var EXP=new Array(256), LOG=new Array(256);
  for(var i=0;i<8;i++) EXP[i]=1<<i;
  for(var i=8;i<256;i++) EXP[i]=EXP[i-4]^EXP[i-5]^EXP[i-6]^EXP[i-8];
  for(var i=0;i<255;i++) LOG[EXP[i]]=i;
  return {
    glog:function(n){ if(n<1) throw new Error('glog('+n+')'); return LOG[n]; },
    gexp:function(n){ while(n<0) n+=255; while(n>=256) n-=255; return EXP[n]; }
  };
})();

function QRPolynomial(num, shift){
  var offset=0;
  while(offset<num.length && num[offset]===0) offset++;
  this.num = new Array(num.length-offset+shift);
  for(var i=0;i<num.length-offset;i++) this.num[i]=num[i+offset];
  for(var i=0;i<shift;i++) this.num[num.length-offset+i]=0;
}
QRPolynomial.prototype.get=function(i){return this.num[i]};
QRPolynomial.prototype.getLength=function(){return this.num.length};
QRPolynomial.prototype.multiply=function(e){
  var num=new Array(this.getLength()+e.getLength()-1);
  for(var i=0;i<num.length;i++) num[i]=0;
  for(var i=0;i<this.getLength();i++){
    for(var j=0;j<e.getLength();j++){
      num[i+j]^=QRMath.gexp(QRMath.glog(this.get(i))+QRMath.glog(e.get(j)));
    }
  }
  return new QRPolynomial(num,0);
};
QRPolynomial.prototype.mod=function(e){
  if(this.getLength()-e.getLength()<0) return this;
  var ratio=QRMath.glog(this.get(0))-QRMath.glog(e.get(0));
  var num=new Array(this.getLength());
  for(var i=0;i<this.getLength();i++) num[i]=this.get(i);
  for(var i=0;i<e.getLength();i++) num[i]^=QRMath.gexp(QRMath.glog(e.get(i))+ratio);
  return new QRPolynomial(num,0).mod(e);
};

function getErrorCorrectPolynomial(ecLength){
  var a=new QRPolynomial([1],0);
  for(var i=0;i<ecLength;i++) a=a.multiply(new QRPolynomial([1,QRMath.gexp(i)],0));
  return a;
}

/* RS block table: [version][ecLevel] -> array of [count, totalCount, dataCount]
   ecLevel index: 0=L 1=M 2=Q 3=H. Only versions 1..20 included (sufficient for our payloads). */
var RS_BLOCK_TABLE = {
1:{L:[[1,26,19]],M:[[1,26,16]],Q:[[1,26,13]],H:[[1,26,9]]},
2:{L:[[1,44,34]],M:[[1,44,28]],Q:[[1,44,22]],H:[[1,44,16]]},
3:{L:[[1,70,55]],M:[[1,70,44]],Q:[[2,35,17]],H:[[2,35,13]]},
4:{L:[[1,100,80]],M:[[2,50,32]],Q:[[2,50,24]],H:[[4,25,9]]},
5:{L:[[1,134,108]],M:[[2,67,43]],Q:[[2,33,15],[2,34,16]],H:[[2,33,11],[2,34,12]]},
6:{L:[[2,86,68]],M:[[4,43,27]],Q:[[4,43,19]],H:[[4,43,15]]},
7:{L:[[2,98,78]],M:[[4,49,31]],Q:[[2,32,14],[4,33,15]],H:[[4,39,13],[1,40,14]]},
8:{L:[[2,121,97]],M:[[2,60,38],[2,61,39]],Q:[[4,40,18],[2,41,19]],H:[[4,40,14],[2,41,15]]},
9:{L:[[2,146,116]],M:[[3,58,36],[2,59,37]],Q:[[4,36,16],[4,37,17]],H:[[4,36,12],[4,37,13]]},
10:{L:[[2,86,68],[2,87,69]],M:[[4,69,43],[1,70,44]],Q:[[6,43,19],[2,44,20]],H:[[6,43,15],[2,44,16]]},
11:{L:[[4,101,81]],M:[[1,80,50],[4,81,51]],Q:[[4,50,22],[4,51,23]],H:[[3,36,12],[8,37,13]]},
12:{L:[[2,116,92],[2,117,93]],M:[[6,58,36],[2,59,37]],Q:[[4,46,20],[6,47,21]],H:[[7,42,14],[4,43,15]]},
13:{L:[[4,133,107]],M:[[8,59,37],[1,60,38]],Q:[[8,44,20],[4,45,21]],H:[[12,33,11],[4,34,12]]},
14:{L:[[3,145,115],[1,146,116]],M:[[4,64,40],[5,65,41]],Q:[[11,36,16],[5,37,17]],H:[[11,36,12],[5,37,13]]},
15:{L:[[5,109,87],[1,110,88]],M:[[5,65,41],[5,66,42]],Q:[[5,54,24],[7,55,25]],H:[[11,36,12],[7,37,13]]},
16:{L:[[5,122,98],[1,123,99]],M:[[7,73,45],[3,74,46]],Q:[[15,43,19],[2,44,20]],H:[[3,45,15],[13,46,16]]},
17:{L:[[1,135,107],[5,136,108]],M:[[10,74,46],[1,75,47]],Q:[[1,50,22],[15,51,23]],H:[[2,42,14],[17,43,15]]},
18:{L:[[5,150,120],[1,151,121]],M:[[9,69,43],[4,70,44]],Q:[[17,50,22],[1,51,23]],H:[[2,42,14],[19,43,15]]},
19:{L:[[3,141,113],[4,142,114]],M:[[3,70,44],[11,71,45]],Q:[[17,47,21],[4,48,22]],H:[[9,39,13],[16,40,14]]},
20:{L:[[3,135,107],[5,136,108]],M:[[3,67,41],[13,68,42]],Q:[[15,54,24],[5,55,25]],H:[[15,43,15],[10,44,16]]}
};

function getRSBlocks(typeNumber, ecLevel){
  var t = RS_BLOCK_TABLE[typeNumber];
  if(!t) throw new Error('bad version '+typeNumber);
  var rows = t[ecLevel];
  var list=[];
  rows.forEach(function(r){
    var count=r[0], total=r[1], data=r[2];
    for(var i=0;i<count;i++) list.push({totalCount:total, dataCount:data});
  });
  return list;
}

function QRBitBuffer(){ this.buffer=[]; this.length=0; }
QRBitBuffer.prototype.get=function(index){
  var bufIndex=Math.floor(index/8);
  return ((this.buffer[bufIndex]>>>(7-index%8))&1)===1;
};
QRBitBuffer.prototype.put=function(num,length){
  for(var i=0;i<length;i++) this.putBit(((num>>>(length-i-1))&1)===1);
};
QRBitBuffer.prototype.putBit=function(bit){
  var bufIndex=Math.floor(this.length/8);
  if(this.buffer.length<=bufIndex) this.buffer.push(0);
  if(bit) this.buffer[bufIndex] |= (0x80>>>(this.length%8));
  this.length++;
};

var PATTERN_POSITION_TABLE=[
[],[6,18],[6,22],[6,26],[6,30],[6,34],[6,22,38],[6,24,42],[6,26,46],[6,28,50],
[6,30,54],[6,32,58],[6,34,62],[6,26,46,66],[6,26,48,70],[6,26,50,74],[6,30,54,78],[6,30,56,82],[6,30,58,86],[6,34,62,90]
];

var G15=(1<<10)|(1<<8)|(1<<5)|(1<<4)|(1<<2)|(1<<1)|(1<<0);
var G18=(1<<12)|(1<<11)|(1<<10)|(1<<9)|(1<<8)|(1<<5)|(1<<2)|(1<<0);
var G15_MASK=(1<<14)|(1<<12)|(1<<10)|(1<<4)|(1<<1);

function getBCHDigit(data){var digit=0; while(data!==0){digit++; data>>>=1;} return digit;}
function getBCHTypeInfo(data){
  var d=data<<10;
  while(getBCHDigit(d)-getBCHDigit(G15)>=0) d ^= (G15 << (getBCHDigit(d)-getBCHDigit(G15)));
  return ((data<<10)|d) ^ G15_MASK;
}
function getBCHTypeNumber(data){
  var d=data<<12;
  while(getBCHDigit(d)-getBCHDigit(G18)>=0) d ^= (G18 << (getBCHDigit(d)-getBCHDigit(G18)));
  return (data<<12)|d;
}

var MASK_FUNCS=[
function(i,j){return (i+j)%2===0},
function(i,j){return i%2===0},
function(i,j){return j%3===0},
function(i,j){return (i+j)%3===0},
function(i,j){return (Math.floor(i/2)+Math.floor(j/3))%2===0},
function(i,j){return (i*j)%2+(i*j)%3===0},
function(i,j){return ((i*j)%2+(i*j)%3)%2===0},
function(i,j){return ((i*j)%3+(i+j)%2)%2===0}
];

function QRCodeModel(typeNumber, ecLevel){
  this.typeNumber=typeNumber;
  this.ecLevel=ecLevel;
  this.modules=null;
  this.moduleCount=0;
  this.dataList=[];
}
QRCodeModel.prototype.addData=function(bytes){ this.dataList.push(bytes); };
QRCodeModel.prototype.isDark=function(row,col){
  if(row<0||this.moduleCount<=row||col<0||this.moduleCount<=col) throw new Error(row+','+col);
  return this.modules[row][col];
};
QRCodeModel.prototype.getModuleCount=function(){return this.moduleCount};

QRCodeModel.prototype.make=function(){
  this.moduleCount = this.typeNumber*4+17;
  this.modules=new Array(this.moduleCount);
  for(var row=0;row<this.moduleCount;row++){
    this.modules[row]=new Array(this.moduleCount);
    for(var col=0;col<this.moduleCount;col++) this.modules[row][col]=null;
  }
  this.setupPositionProbePattern(0,0);
  this.setupPositionProbePattern(this.moduleCount-7,0);
  this.setupPositionProbePattern(0,this.moduleCount-7);
  this.setupPositionAdjustPattern();
  this.setupTimingPattern();
  this.setupTypeInfo(true,0); // temp, real mask chosen later

  if(this.typeNumber>=7) this.setupTypeNumber(true);

  var dataBits = this.createData();
  this.mapData(dataBits, 0); // temp pass not used; we do final below

  // Try all masks, score, pick best
  var bestMask=0, bestLost=Infinity, bestModules=null;
  for(var m=0;m<8;m++){
    // reset modules (keep function patterns, clear data area)
    this.resetDataModules();
    this.setupTypeInfo(false,m);
    if(this.typeNumber>=7) this.setupTypeNumber(false);
    this.mapData(dataBits, m);
    var lost=this.getLostPoint();
    if(lost<bestLost){ bestLost=lost; bestMask=m; bestModules=this.cloneModules(); }
  }
  this.modules=bestModules;
  this.maskPattern=bestMask;
};

QRCodeModel.prototype.cloneModules=function(){
  var c=new Array(this.moduleCount);
  for(var r=0;r<this.moduleCount;r++) c[r]=this.modules[r].slice();
  return c;
};

QRCodeModel.prototype.resetDataModules=function(){
  // null out everything, then redraw function patterns (probe, timing, adjust)
  for(var row=0;row<this.moduleCount;row++)
    for(var col=0;col<this.moduleCount;col++) this.modules[row][col]=null;
  this.setupPositionProbePattern(0,0);
  this.setupPositionProbePattern(this.moduleCount-7,0);
  this.setupPositionProbePattern(0,this.moduleCount-7);
  this.setupPositionAdjustPattern();
  this.setupTimingPattern();
};

QRCodeModel.prototype.setupPositionProbePattern=function(row,col){
  for(var r=-1;r<=7;r++){
    if(row+r<=-1||this.moduleCount<=row+r) continue;
    for(var c=-1;c<=7;c++){
      if(col+c<=-1||this.moduleCount<=col+c) continue;
      if((0<=r&&r<=6&&(c===0||c===6)) || (0<=c&&c<=6&&(r===0||r===6)) || (2<=r&&r<=4&&2<=c&&c<=4))
        this.modules[row+r][col+c]=true;
      else this.modules[row+r][col+c]=false;
    }
  }
};

QRCodeModel.prototype.setupTimingPattern=function(){
  for(var r=8;r<this.moduleCount-8;r++){
    if(this.modules[r][6]!==null) continue;
    this.modules[r][6]=(r%2===0);
  }
  for(var c=8;c<this.moduleCount-8;c++){
    if(this.modules[6][c]!==null) continue;
    this.modules[6][c]=(c%2===0);
  }
};

QRCodeModel.prototype.setupPositionAdjustPattern=function(){
  var pos=PATTERN_POSITION_TABLE[this.typeNumber-1];
  if(!pos) return;
  for(var i=0;i<pos.length;i++){
    for(var j=0;j<pos.length;j++){
      var row=pos[i], col=pos[j];
      if(this.modules[row][col]!==null) continue;
      for(var r=-2;r<=2;r++){
        for(var c=-2;c<=2;c++){
          if(r===-2||r===2||c===-2||c===2||(r===0&&c===0)) this.modules[row+r][col+c]=true;
          else this.modules[row+r][col+c]=false;
        }
      }
    }
  }
};

QRCodeModel.prototype.setupTypeNumber=function(test){
  var bits=getBCHTypeNumber(this.typeNumber);
  for(var i=0;i<18;i++){
    var mod=(!test && ((bits>>i)&1)===1);
    this.modules[Math.floor(i/3)][i%3+this.moduleCount-8-3]=mod;
  }
  for(var i=0;i<18;i++){
    var mod=(!test && ((bits>>i)&1)===1);
    this.modules[i%3+this.moduleCount-8-3][Math.floor(i/3)]=mod;
  }
};

var EC_LEVEL_BITS={L:1,M:0,Q:3,H:2};
QRCodeModel.prototype.setupTypeInfo=function(test,maskPattern){
  var data=(EC_LEVEL_BITS[this.ecLevel]<<3)|maskPattern;
  var bits=getBCHTypeInfo(data);
  for(var i=0;i<15;i++){
    var mod=(!test && ((bits>>i)&1)===1);
    if(i<6) this.modules[i][8]=mod;
    else if(i<8) this.modules[i+1][8]=mod;
    else this.modules[this.moduleCount-15+i][8]=mod;
  }
  for(var i=0;i<15;i++){
    var mod=(!test && ((bits>>i)&1)===1);
    if(i<8) this.modules[8][this.moduleCount-i-1]=mod;
    else if(i<9) this.modules[8][15-i-1+1]=mod;
    else this.modules[8][15-i-1]=mod;
  }
  this.modules[this.moduleCount-8][8]=(!test);
};

QRCodeModel.prototype.createData=function(){
  var rsBlocks=getRSBlocks(this.typeNumber, this.ecLevel);
  var buffer=new QRBitBuffer();
  for(var i=0;i<this.dataList.length;i++){
    var bytes=this.dataList[i];
    buffer.put(4,4); // byte mode indicator 0100
    var lenBits = this.typeNumber<10?8:16;
    buffer.put(bytes.length, lenBits);
    for(var j=0;j<bytes.length;j++) buffer.put(bytes[j],8);
  }
  var totalDataCount=0;
  for(var i=0;i<rsBlocks.length;i++) totalDataCount+=rsBlocks[i].dataCount;
  if(buffer.length > totalDataCount*8) throw new Error('data overflow for this QR version');
  if(buffer.length + 4 <= totalDataCount*8) buffer.put(0,4);
  while(buffer.length%8!==0) buffer.putBit(false);
  var PAD0=0xEC, PAD1=0x11;
  while(true){
    if(buffer.length>=totalDataCount*8) break;
    buffer.put(PAD0,8);
    if(buffer.length>=totalDataCount*8) break;
    buffer.put(PAD1,8);
  }
  return this.createBytes(buffer, rsBlocks);
};

QRCodeModel.prototype.createBytes=function(buffer, rsBlocks){
  var offset=0;
  var maxDcCount=0, maxEcCount=0;
  var dcdata=new Array(rsBlocks.length), ecdata=new Array(rsBlocks.length);
  for(var r=0;r<rsBlocks.length;r++){
    var dcCount=rsBlocks[r].dataCount, ecCount=rsBlocks[r].totalCount-dcCount;
    maxDcCount=Math.max(maxDcCount,dcCount);
    maxEcCount=Math.max(maxEcCount,ecCount);
    dcdata[r]=new Array(dcCount);
    for(var i=0;i<dcdata[r].length;i++) dcdata[r][i]=0xff & buffer.buffer[i+offset];
    offset+=dcCount;
    var rsPoly=getErrorCorrectPolynomial(ecCount);
    var rawPoly=new QRPolynomial(dcdata[r], rsPoly.getLength()-1);
    var modPoly=rawPoly.mod(rsPoly);
    ecdata[r]=new Array(rsPoly.getLength()-1);
    for(var i=0;i<ecdata[r].length;i++){
      var modIndex=i+modPoly.getLength()-ecdata[r].length;
      ecdata[r][i]=(modIndex>=0)?modPoly.get(modIndex):0;
    }
  }
  var totalCodeCount=0;
  for(var i=0;i<rsBlocks.length;i++) totalCodeCount+=rsBlocks[i].totalCount;
  var data=new Array(totalCodeCount);
  var index=0;
  for(var i=0;i<maxDcCount;i++) for(var r=0;r<rsBlocks.length;r++) if(i<dcdata[r].length) data[index++]=dcdata[r][i];
  for(var i=0;i<maxEcCount;i++) for(var r=0;r<rsBlocks.length;r++) if(i<ecdata[r].length) data[index++]=ecdata[r][i];
  return data;
};

QRCodeModel.prototype.mapData=function(data, maskPattern){
  var inc=-1, row=this.moduleCount-1, bitIndex=7, byteIndex=0;
  var maskFunc=MASK_FUNCS[maskPattern];
  for(var col=this.moduleCount-1; col>0; col-=2){
    if(col===6) col--;
    while(true){
      for(var c=0;c<2;c++){
        if(this.modules[row][col-c]===null){
          var dark=false;
          if(byteIndex<data.length) dark=(((data[byteIndex]>>>bitIndex)&1)===1);
          var mask=maskFunc(row,col-c);
          if(mask) dark=!dark;
          this.modules[row][col-c]=dark;
          bitIndex--;
          if(bitIndex===-1){byteIndex++;bitIndex=7;}
        }
      }
      row+=inc;
      if(row<0||this.moduleCount<=row){row-=inc;inc=-inc;break;}
    }
  }
};

QRCodeModel.prototype.getLostPoint=function(){
  var moduleCount=this.moduleCount, lostPoint=0;
  // rule 1: consecutive same-color in row/col
  for(var row=0;row<moduleCount;row++){
    for(var col=0;col<moduleCount;col++){
      var sameCount=0; var dark=this.modules[row][col];
      for(var r=-1;r<=1;r++){
        if(row+r<0||moduleCount<=row+r) continue;
        for(var c=-1;c<=1;c++){
          if(col+c<0||moduleCount<=col+c) continue;
          if(r===0&&c===0) continue;
          if(dark===this.modules[row+r][col+c]) sameCount++;
        }
      }
      if(sameCount>5) lostPoint += (3+sameCount-5);
    }
  }
  // rule 2: 2x2 blocks same color
  for(var row=0;row<moduleCount-1;row++){
    for(var col=0;col<moduleCount-1;col++){
      var count=0;
      if(this.modules[row][col]) count++;
      if(this.modules[row+1][col]) count++;
      if(this.modules[row][col+1]) count++;
      if(this.modules[row+1][col+1]) count++;
      if(count===0||count===4) lostPoint+=3;
    }
  }
  // rule 3: specific patterns 1011101 with 4 light before/after
  for(var row=0;row<moduleCount;row++){
    for(var col=0;col<moduleCount-6;col++){
      if(this.modules[row][col] && !this.modules[row][col+1] && this.modules[row][col+2] && this.modules[row][col+3] && this.modules[row][col+4] && !this.modules[row][col+5] && this.modules[row][col+6])
        lostPoint+=40;
    }
  }
  for(var col=0;col<moduleCount;col++){
    for(var row=0;row<moduleCount-6;row++){
      if(this.modules[row][col] && !this.modules[row+1][col] && this.modules[row+2][col] && this.modules[row+3][col] && this.modules[row+4][col] && !this.modules[row+5][col] && this.modules[row+6][col])
        lostPoint+=40;
    }
  }
  // rule 4: dark module ratio
  var darkCount=0;
  for(var row=0;row<moduleCount;row++) for(var col=0;col<moduleCount;col++) if(this.modules[row][col]) darkCount++;
  var ratio=Math.abs(100*darkCount/moduleCount/moduleCount-50)/5;
  lostPoint+=ratio*10;
  return lostPoint;
};

function utf8Bytes(str){
  var bytes=[];
  for(var i=0;i<str.length;i++){
    var c=str.codePointAt(i);
    if(c>0xFFFF) i++;
    if(c<0x80) bytes.push(c);
    else if(c<0x800){ bytes.push(0xc0|(c>>6), 0x80|(c&0x3f)); }
    else if(c<0x10000){ bytes.push(0xe0|(c>>12), 0x80|((c>>6)&0x3f), 0x80|(c&0x3f)); }
    else { bytes.push(0xf0|(c>>18), 0x80|((c>>12)&0x3f), 0x80|((c>>6)&0x3f), 0x80|(c&0x3f)); }
  }
  return bytes;
}

function generateQRMatrix(text, ecLevel, minVersion){
  ecLevel = ecLevel || 'M';
  var bytes = utf8Bytes(text);
  for(var v=(minVersion||1); v<=20; v++){
    try{
      var qr = new QRCodeModel(v, ecLevel);
      qr.addData(bytes);
      qr.make();
      return qr;
    }catch(e){
      if(v===20) throw e;
      continue;
    }
  }
}



