/* ── QR rendering helpers ─────────────────────────────────── */
function nbqrSvgString(text,ecLevel){
var qr=generateQRMatrix(text,ecLevel||'M');
var n=qr.getModuleCount(),quiet=2,view=n+quiet*2,rects='';
for(var r=0;r<n;r++)for(var c=0;c<n;c++)if(qr.isDark(r,c))rects+='<rect x="'+(c+quiet)+'" y="'+(r+quiet)+'" width="1" height="1"/>';
return '<svg viewBox="0 0 '+view+' '+view+'" xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges"><rect width="'+view+'" height="'+view+'" fill="#fff"/><g fill="#1f2a26">'+rects+'</g></svg>';
}
function nbqrDrawOnCanvas(ctx,text,ecLevel,x,y,sizePx){
var qr=generateQRMatrix(text,ecLevel||'M');
var n=qr.getModuleCount(),quiet=2,totalModules=n+quiet*2,modulePx=sizePx/totalModules;
ctx.fillStyle='#ffffff';ctx.fillRect(x,y,sizePx,sizePx);
ctx.fillStyle='#1f2a26';
for(var r=0;r<n;r++)for(var c=0;c<n;c++)if(qr.isDark(r,c))ctx.fillRect(x+(c+quiet)*modulePx,y+(r+quiet)*modulePx,modulePx+0.6,modulePx+0.6);
}

/* ── Certificate verification ────────────────────────────── */
var NB_CERT_BASE_URL='https://nabtex.vercel.app/';
var NB_CERT_SALT='NBX-IPM-2026';
/* English/Arabic course names shown on the certificate — keyed by course id (AC_CID) */
var AC_CERT_TITLES={
'pest':{en:'Integrated Pest Management',abbr:'IPM',ar:'مكافحة الآفات الزراعية المتكاملة'},
'mol-bio':{en:'Molecular Biology Techniques',abbr:'',ar:'تقنيات البيولوجيا الجزيئية'},
'food-quality':{en:'Food Quality and Safety',abbr:'',ar:'جودة الغذاء وسلامته'},
'ag-english':{en:'Agricultural English',abbr:'',ar:'اللغة الإنجليزية الزراعية'},
'food-safety':{en:'Food Safety',abbr:'',ar:'سلامة الغذاء'},
'land-reclamation':{en:'Land Reclamation and Fertilization Programs',abbr:'',ar:'استصلاح الأراضي ووضع برامج التسميد'},
'tissue-culture':{en:'Plant Tissue Culture',abbr:'',ar:'زراعة الأنسجة النباتية وتطبيقاتها الحديثة'},
'bioinformatics':{en:'Bioinformatics',abbr:'',ar:'المعلوماتية الحيوية'}
};
function acCertCourseInfo(cid){
var info=AC_CERT_TITLES[cid]||AC_CERT_TITLES.pest;
return{en:info.en,abbr:info.abbr,ar:info.ar,enFull:info.abbr?(info.en+' ('+info.abbr+')'):info.en};
}
function nbCertSign(name,date,cid){
/* cid omitted => legacy literal 'ipm' prefix, so certificates generated before
   course-aware signing was added keep verifying exactly as before. */
var pfx=cid||'ipm';
var str=pfx+'|'+name+'|'+date+'|'+NB_CERT_SALT,h=5381;
for(var i=0;i<str.length;i++){h=((h*33)^str.charCodeAt(i))>>>0}
var hex=(h>>>0).toString(16);
while(hex.length<8)hex='0'+hex;
return hex;
}
function nbCertVerifyUrl(name,date,cid){
var c=cid||'pest';
return NB_CERT_BASE_URL+'?nbcert=ipm&n='+encodeURIComponent(name)+'&d='+encodeURIComponent(date)+'&c='+encodeURIComponent(c)+'&s='+nbCertSign(name,date,c);
}
function nbCheckCertVerify(){
var params;
try{params=new URLSearchParams(location.search)}catch(e){return}
if(!params.has('nbcert'))return;
var name=params.get('n')||'',date=params.get('d')||'',sig=params.get('s')||'';
var cid=params.get('c')||null;
var validSig=name&&date&&nbCertSign(name,date,cid)===sig;
if(!document.getElementById('nb-verify-style')){
var st=document.createElement('style');st.id='nb-verify-style';
st.textContent='#nb-verify-overlay{position:fixed;inset:0;z-index:99999;background:#dbe4dd;display:flex;align-items:center;justify-content:center;padding:24px;font-family:Cairo,sans-serif}.nbv-card{background:#fff;border:1.5px solid #84958d;border-radius:12px;padding:40px 32px;max-width:420px;width:100%;text-align:center;box-shadow:0 20px 60px rgba(20,40,30,.25)}.nbv-logo{width:64px;height:64px;border-radius:50%;object-fit:cover;margin-bottom:16px}.nbv-badge{width:56px;height:56px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:800;margin:0 auto 14px;color:#fff}.nbv-badge.nbv-ok{background:#1f6e42}.nbv-badge.nbv-warn{background:#c0392b}.nbv-title{font-family:"Cormorant Garamond",serif;font-size:1.6rem;color:#28352f;margin:0 0 4px}.nbv-sub{font-size:13px;color:#5e6f69;margin:0 0 22px}.nbv-rows{text-align:right;border-top:1px solid #e2e8e4;padding-top:16px;margin-bottom:24px}.nbv-row{display:flex;justify-content:space-between;gap:10px;padding:8px 0;font-size:13px;border-bottom:1px dashed #e2e8e4}.nbv-k{color:#5e6f69;flex-shrink:0}.nbv-v{color:#28352f;font-weight:700;text-align:left;word-break:break-word}.nbv-btn{width:100%;padding:13px;border-radius:9999px;border:none;background:#1B6B3A;color:#fff;font-weight:700;font-size:14px;cursor:pointer;font-family:Cairo,sans-serif}';
document.head.appendChild(st);
var meta=document.createElement('meta');meta.name='robots';meta.content='noindex,nofollow';document.head.appendChild(meta);
}
var overlay=document.createElement('div');
overlay.id='nb-verify-overlay';
overlay.innerHTML=
'<div class="nbv-card">'+
'<img decoding="async" class="nbv-logo" src="'+ACAD_LOGO_DATAURI+'" alt="Nabtex">'+
(validSig?
'<div class="nbv-badge nbv-ok">✓</div><h2 class="nbv-title">Certificate Verified</h2><p class="nbv-sub">شهادة موثقة من نبتيكس أكاديمي</p>'
:
'<div class="nbv-badge nbv-warn">!</div><h2 class="nbv-title">Could Not Verify</h2><p class="nbv-sub">تعذر التحقق من صحة بيانات هذه الشهادة</p>'
)+
'<div class="nbv-rows">'+
'<div class="nbv-row"><span class="nbv-k">Name / الاسم</span><span class="nbv-v">'+acEsc(name||'—')+'</span></div>'+
'<div class="nbv-row"><span class="nbv-k">Course / الدورة</span><span class="nbv-v">'+acEsc(acCertCourseInfo(cid||'pest').enFull)+'</span></div>'+
'<div class="nbv-row"><span class="nbv-k">Date / التاريخ</span><span class="nbv-v">'+acEsc(date||'—')+'</span></div>'+
'</div>'+
'<button class="nbv-btn" id="nb-verify-close">Visit Nabtex — زيارة نبتيكس</button>'+
'</div>';
document.body.appendChild(overlay);
document.getElementById('nb-verify-close').addEventListener('click',function(){
overlay.remove();
history.replaceState(null,'',location.pathname);
});
}
nbCheckCertVerify();

/* ── Progress ─────────────────────────────────────────────── */

/* ── User-scoped progress key: prevents data cross-contamination between accounts ── */
function acProgKey(){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
var pf='nb-'+AC_CID+'-p';return u?(pf+'__'+u):(pf+'__guest');
}
function acProg(){
try{
var key=acProgKey();
var raw=localStorage.getItem(key);
if(raw===null&&AC_CID==='pest'){
/* One-time migration from legacy shared key (pre multi-account support) */
var legacy=localStorage.getItem('nb-pest-p');
if(legacy){raw=legacy;try{localStorage.setItem(key,legacy);localStorage.removeItem('nb-pest-p')}catch(e){}}
}
return JSON.parse(raw||'{}')
}catch(e){return{}}
}
function acSave(p){try{localStorage.setItem(acProgKey(),JSON.stringify(p))}catch(e){}acPushCloud(AC_CID,p);}
/* Clears a specific user's local academy progress (called on logout / account switch) */
function acClearLocalProgress(targetUid){
['pest','mol-bio','food-quality','ag-english','food-safety','land-reclamation','tissue-culture','bioinformatics'].forEach(function(cid){
var pf='nb-'+cid+'-p';
var key=targetUid?(pf+'__'+targetUid):(pf+'__guest');
try{localStorage.removeItem(key)}catch(e){}});
}
window._acClearLocalProgress=acClearLocalProgress;

/* ── Cloud Sync (Firestore) ───────────────────────────────────
   Keeps course progress in sync across devices for the same account.
   The local copy stays the source of truth for instant UI; Firestore is
   only used to carry progress between devices. Fails silently if offline —
   local progress is never lost or blocked by a network issue. */
var _acPushTimers={};
function acPushCloud(cid,p){
try{
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u||typeof db==='undefined'||!db)return;
clearTimeout(_acPushTimers[cid]);
_acPushTimers[cid]=setTimeout(function(){
db.collection('academy_progress').doc(u+'_'+cid).set({
uid:u,courseId:cid,d:p.d||[],dt:p.dt||{},fe:(p.fe!==undefined?p.fe:-1),updatedAt:Date.now()
},{merge:true}).catch(function(e){console.warn('[Academy] cloud sync (up) failed',e)});
},700);
}catch(e){}}
/* Pulls cloud progress for every course and merges it with the local copy —
   union of completed lessons, earliest completion time (keeps the 24h unit
   gate fair), highest final-exam score. Runs once on login so progress made
   on another phone shows up here too. No-op for guests / when Firestore
   isn't ready. */
function acPullCloud(){
return new Promise(function(resolve){
try{
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u||typeof db==='undefined'||!db){resolve();return;}
var cids=['pest','mol-bio','food-quality','ag-english','food-safety','land-reclamation','tissue-culture','bioinformatics'],pending=cids.length;
function step(){pending--;if(pending<=0)resolve();}
cids.forEach(function(cid){
var key='nb-'+cid+'-p__'+u;
db.collection('academy_progress').doc(u+'_'+cid).get().then(function(snap){
var local={};try{local=JSON.parse(localStorage.getItem(key)||'{}')}catch(e){local={}}
var cloud=snap.exists?(snap.data()||{}):{};
var cloudD=cloud.d||[],localD=local.d||[];
var mergedD=Array.from(new Set(localD.concat(cloudD)));
var mergedDt={};
Object.keys(Object.assign({},cloud.dt||{},local.dt||{})).forEach(function(lid){
var cv=(cloud.dt||{})[lid],lv=(local.dt||{})[lid];
mergedDt[lid]=(cv&&lv)?Math.min(cv,lv):(cv||lv);
});
var cloudFe=cloud.fe!==undefined?cloud.fe:-1,localFe=local.fe!==undefined?local.fe:-1;
var mergedFe=Math.max(cloudFe,localFe);
try{localStorage.setItem(key,JSON.stringify({d:mergedD,dt:mergedDt,fe:mergedFe}))}catch(e){}
if(mergedD.length!==cloudD.length||mergedFe!==cloudFe){
db.collection('academy_progress').doc(u+'_'+cid).set({
uid:u,courseId:cid,d:mergedD,dt:mergedDt,fe:mergedFe,updatedAt:Date.now()
},{merge:true}).catch(function(e){console.warn('[Academy] cloud sync (up) failed',e)});
}
step();
}).catch(function(e){console.warn('[Academy] cloud sync (down) failed',e);step()});
});
}catch(e){resolve()}
});
}
window._acSyncCloudProgress=function(){
return acPullCloud().then(function(){
var r=document.getElementById('acad-root');
if(r&&r.firstChild&&typeof acR==='function'){try{acR()}catch(e){}}
});
};
function acDone(id){return(acProg().d||[]).includes(id)}
function acMark(id){var p=acProg();p.d=p.d||[];if(!p.d.includes(id))p.d.push(id);p.dt=p.dt||{};p.dt[id]=Date.now();acSave(p)}
function acPct(){
/* Certificate already earned (final exam passed) — keep progress at 100% permanently.
   Prevents later additions to the course content from retroactively shrinking the
   percentage (and hiding the certificate) for users who already completed it. */
if(acFEScore()>=70)return 100;
var total=AC_COURSE.modules.reduce(function(s,m){return s+m.lessons.length},0);
var done=(acProg().d||[]).length;
return total?Math.round(done/total*100):0}
function acFEScore(){var v=acProg().fe;return v!==undefined?v:-1}

/* ── Sequential Lesson Order/Lock ─────────────────────────── */

function acFlatLessons(){
var arr=[];
AC_COURSE.modules.forEach(function(m){m.lessons.forEach(function(ls){arr.push(ls.id)})});
return arr}
/* Unit (module) day-gate: once the last lesson of a module is completed,
   the next module's first lesson stays locked for 24 hours. */
var AC_UNIT_GATE_MS=0;
function acModuleGateMap(){
if(AC_CID==='land-reclamation')return{};
var map={};
for(var i=1;i<AC_COURSE.modules.length;i++){
 var prevLessons=AC_COURSE.modules[i-1].lessons;
 var curLessons=AC_COURSE.modules[i].lessons;
 if(prevLessons.length&&curLessons.length)
  map[curLessons[0].id]=prevLessons[prevLessons.length-1].id}
return map}
function acUnitGateRemaining(id){
var gateLessonId=acModuleGateMap()[id];
if(!gateLessonId)return 0;
var dt=(acProg().dt||{})[gateLessonId];
if(!dt)return 0;
var remain=AC_UNIT_GATE_MS-(Date.now()-dt);
return remain>0?remain:0}
function acFormatRemaining(ms){
var totalMin=Math.max(1,Math.ceil(ms/60000));
var h=Math.floor(totalMin/60),m=totalMin%60;
if(h<=0)return m+' دقيقة';
if(m<=0)return h+' ساعة';
return h+' ساعة و'+m+' دقيقة'}
function acIsUnlocked(id){
var flat=acFlatLessons();
var idx=flat.indexOf(id);
if(idx<=0)return true;
if(!acDone(flat[idx-1]))return false;
return acUnitGateRemaining(id)<=0}
function acNextLessonId(id){
var flat=acFlatLessons();
var idx=flat.indexOf(id);
if(idx===-1||idx>=flat.length-1)return null;
return flat[idx+1]}
function acSaveFE(score){var p=acProg();p.fe=score;acSave(p)}

/* ── Answer-order randomization (balanced: even spread of the correct
   position within EACH quiz attempt, not just over many attempts) ── */

function acFisherShuffleArr(arr){
var a=arr.slice();
for(var i=a.length-1;i>0;i--){
 var j=Math.floor(Math.random()*(i+1));
 var t=a[i];a[i]=a[j];a[j]=t;
}
return a}
function acBalancedPositions(n,slots){
var base=Math.floor(n/slots),rem=n%slots;
var slotOrder=acFisherShuffleArr([0,1,2,3].slice(0,slots));
var counts={};
slotOrder.forEach(function(s,i){counts[s]=base+(i<rem?1:0)});
var arr=[];
for(var p=0;p<slots;p++)for(var c=0;c<counts[p];c++)arr.push(p);
return acFisherShuffleArr(arr)}
function acShuffleOptsToPosition(q,targetPos){
var n=q.opts.length;
var others=[];
for(var i=0;i<n;i++)if(i!==q.cor)others.push(i);
others=acFisherShuffleArr(others);
var idxs=new Array(n);
idxs[targetPos]=q.cor;
var oi=0;
for(var p=0;p<n;p++){
 if(p===targetPos)continue;
 idxs[p]=others[oi++];
}
return{q:q.q,opts:idxs.map(function(i){return q.opts[i]}),cor:targetPos,exp:q.exp}}
function acShuffleQuestions(questions){
var n=questions.length;
if(!n)return[];
var slots=questions[0].opts.length;
var positions=acBalancedPositions(n,slots);
return questions.map(function(q,i){return acShuffleOptsToPosition(q,positions[i])})}

/* ── State ────────────────────────────────────────────────── */

var AC={view:'catalog',lid:null,qState:null};

function acGo(view,lid){
/* Free-preview teaser: the course info page, and its "first lecture free"
   deep-link, stay reachable without login — but only for the monetized
   courses this applies to. Every other view/course keeps the guard below. */
var acFreeTeaser=(view==='info'||(view==='lesson'&&lid&&acFlatLessons()[0]===lid))&&(AC_CID==='mol-bio'||AC_CID==='food-safety'||AC_CID==='tissue-culture');
if(view!=='catalog'&&!acFreeTeaser&&!(typeof currentUser!=='undefined'&&currentUser)){
 if(typeof showToast==='function')showToast('سجّل الدخول أو أنشئ حساباً جديداً للبدء في الدورة','inf');
 if(typeof openAuth==='function')openAuth('login');
 view='catalog';lid=null;
}
if((view==='lesson'||view==='quiz')&&lid&&!acIsUnlocked(lid)){
 if(typeof showToast==='function'){
  var gateRem=acUnitGateRemaining(lid);
  showToast(gateRem>0?'أحسنت! الوحدة التالية تفتح غدًا':'أكمل المحاضرة السابقة واجتز اختبارها أولاً',gateRem>0?'inf':'err')
 }
 view='home';lid=null;
}
AC.view=view;AC.lid=lid||null;
if(view==='quiz'){
 var qz=AC_QUIZZES[lid];
 AC.qState={step:0,answers:[],revealed:false,qs:qz?acShuffleQuestions(qz.questions):[]};
}else if(view==='final-exam'){
 AC.qState={step:0,answers:[],revealed:false,qs:acShuffleQuestions(AC_FINAL_EXAM.questions)};
}
acR();window.scrollTo(0,0)}

/* ── Root Render ──────────────────────────────────────────── */

function acR(){
var root=document.getElementById('acad-root');
if(!root)return;
if(AC.view==='catalog'){root.innerHTML=acRenderCatalog();acRefreshCatalogStatuses();}
else if(AC.view==='home')root.innerHTML=acRenderHome();
else if(AC.view==='info')root.innerHTML=acRenderInfo();
else if(AC.view==='lesson'){root.innerHTML=acRenderLesson();if(typeof tcEnhanceVideos==='function')tcEnhanceVideos();}
else if(AC.view==='quiz'){root.innerHTML=acRenderQuiz();acBindQuiz()}
else if(AC.view==='final-exam'){root.innerHTML=acRenderFinalExam();}
else if(AC.view==='cert')root.innerHTML=acRenderCert();
}

/* Silently re-checks payment status against Firestore whenever the catalog
   is shown, so an admin-approved payment reflects instantly instead of
   waiting for the user to click into the course (which was previously the
   only place the local cache got refreshed). Purely additive: falls back
   to the existing cached badges if anything here fails or is unavailable. */
function acRefreshCatalogStatuses(){
try{
if(!(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid))return;
var before=(typeof acMbStatus==='function'?acMbStatus():'')+'|'+(typeof acFsStatus==='function'?acFsStatus():'');
var pending=0,done=function(){
pending--;
if(pending===0){
var after=(typeof acMbStatus==='function'?acMbStatus():'')+'|'+(typeof acFsStatus==='function'?acFsStatus():'');
if(after!==before&&AC.view==='catalog')acR();
}
};
if(typeof acCheckMbAccess==='function'){pending++;acCheckMbAccess(function(){done()});}
if(typeof acCheckFsAccess==='function'){pending++;acCheckFsAccess(function(){done()});}
}catch(e){}
}

