var _MB_VCASH_NUM='01095282573'; /* ← غيّر هنا برقم فودافون كاش */
var _MB_COURSE_PRICE=70;          /* ← السعر بالجنيه              */
var _MB_INSTAPAY_INFO={handle:'',mobile:'01095282573',iban:''}; /* ← يملأها المالك: معرّف/موبايل/IBAN — اترك أي حقل فارغاً لإخفائه */

/* Returns locally-cached status: 'paid' | 'pending' | 'none' */
function acMbStatus(){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u)return 'none';
try{
if(localStorage.getItem('nb-mol-bio-access__'+u)==='paid')return 'paid';
if(localStorage.getItem('nb-mol-bio-pending__'+u)==='true')return 'pending';
}catch(e){}
return 'none';
}
window.acMbStatus=acMbStatus; /* تعريض عالمي — يستخدمه كاروسيل الكورسات في الرئيسية */

/* Async check against Firestore, updates local cache */
function acCheckMbAccess(cb){
var u=(typeof currentUser!=='undefined'&&currentUser&&currentUser.uid)?currentUser.uid:null;
if(!u){cb('none');return;}
var cacheKey='nb-mol-bio-access__'+u;
/* Always check Firestore so admin suspension is enforced immediately */
db.collection('users').doc(u).get().then(function(snap){
var data=snap.exists?snap.data():{};
/* Suspension overrides all other access — clears local cache */
if(data.suspendedCourses&&data.suspendedCourses.indexOf('mol-bio')>-1){
try{localStorage.removeItem(cacheKey);}catch(e){}
cb('suspended');return;
}
/* Cache fast-path (only when not suspended) */
try{if(localStorage.getItem(cacheKey)==='paid'){cb('paid');return;}}catch(e){}
if(data.paidCourses&&data.paidCourses.indexOf('mol-bio')>-1){
try{localStorage.setItem(cacheKey,'paid');}catch(e){}
cb('paid');return;
}
/* Check course_payments for pending/approved */
db.collection('course_payments').where('uid','==',u).get().then(function(qs){
if(qs.empty){cb('none');return;}
var docs=qs.docs.filter(function(d){return d.data().courseId==='mol-bio';});
if(!docs.length){cb('none');return;}
var st=docs[0].data().status;
if(st==='approved'){
try{localStorage.setItem(cacheKey,'paid');}catch(e){}
cb('paid');
}else if(st==='rejected'){
try{localStorage.removeItem('nb-mol-bio-pending__'+u);}catch(e){}
cb('rejected',docs[0].data().rejectionNote||'');
}else{
try{localStorage.setItem('nb-mol-bio-pending__'+u,'true');}catch(e){}
cb('pending');
}
}).catch(function(){cb('none');});
}).catch(function(){cb('none');});
}

