openFirst:function(){
/* Certificate already earned — go straight to it. Guards this function the same
   way acPct() is guarded, in case anything besides the home-page button ever
   calls openFirst() directly for a graduated user. */
if(acFEScore()>=70){acGo('cert',null);return;}
var firstReady=null;
for(var i=0;i<AC_COURSE.modules.length&&!firstReady;i++)
 for(var j=0;j<AC_COURSE.modules[i].lessons.length&&!firstReady;j++)
  if(!acDone(AC_COURSE.modules[i].lessons[j].id))firstReady=AC_COURSE.modules[i].lessons[j].id;
if(firstReady)acGo('lesson',firstReady);else acGo('cert',null)},
